// ===========================================================================
#define PATCH_FULL_SUITE(SUITE, ISA)                                           \
  TEST(SUITE, ArithMix) { checkEquiv(ISA, buildArithMixIR, "amix", kPairs); }  \
  TEST(SUITE, MultiWayBranch) {                                                \
    checkEquiv(ISA, buildMultiWayBranchIR, "mwbr", kPairs);                    \
  }                                                                            \
  TEST(SUITE, MutualRecursion) {                                               \
    checkEquiv(ISA, buildMutualRecursionIR, "mrec", kPairs);                   \
  }                                                                            \
  TEST(SUITE, LoopBreak) {                                                     \
    checkEquiv(ISA, buildLoopBreakIR, "lbreak", kPairs);                       \
  }                                                                            \
  TEST(SUITE, RegPressure) {                                                   \
    checkEquiv(ISA, buildRegPressureIR, "regpress", kPairs);                   \
  }                                                                            \
  TEST(SUITE, WideMul64Var) {                                                  \
    checkEquiv(ISA, buildWideMul64IR, "wmul64", kPairs);                       \
  }                                                                            \
  TEST(SUITE, FnPtrSel) {                                                      \
    checkEquiv(ISA, buildFnPtrSelIR, "fnptrsel", kPairs);                      \
  }                                                                            \
  TEST(SUITE, VtDisp) { checkEquiv(ISA, buildVtDispIR, "vtdisp", kPairs); }    \
