// ASLR (fnptr-array-note): regression guard for the code-pointer-mirror
// externalization fix.  Without it the patched binary deterministically
// SIGSEGV'd (the `@__nd_codeptr_*` mirror held absolute recompiled VAs in a
// read-only injected segment with no rebase records).  Checks exit code +
// stdout (a crash leaves stdout empty).
TEST(PatchFullFnPtr_HostE2E, FnPtrSectionPreservesOutput) {
  runHostE2EStringOutput("section", kHostFnPtrProgram, "fnptr");
}

TEST(PatchFullFnPtr_HostE2E, FnPtrInplacePreservesOutput) {
  runHostE2EStringOutput("inplace", kHostFnPtrProgram, "fnptr");
}

